808: function findNearestEnemy(range = 200) {
809:   let nearest = null;
810:   let nearestDistance = Infinity;
811:   for (const enemy of state.enemies) {
812:     const d = dist(enemy, state.player);
813:     if (d < range && d < nearestDistance) {
814:       nearest = enemy;
815:       nearestDistance = d;
816:     }
817:   }
818:   return nearest;
819: }
