821: function updatePlayer(dt) {
822:   const p = state.player;
823:   if (!p) return;
824: 
825:   p.attackCooldown = Math.max(0, p.attackCooldown - dt);
826:   p.dodgeCooldown = Math.max(0, p.dodgeCooldown - dt);
827:   p.invulnerable = Math.max(0, p.invulnerable - dt);
828:   p.satiety = Math.max(0, p.satiety - dt * 0.9);
829: 
830:   if (p.satiety <= 0) {
831:     p.hp -= dt * 7;
832:     if (p.hp <= 0) die();
833:   }
834: 
835:   const moveX = state.input.x;
836:   const moveY = state.input.y;
837:   const len = Math.hypot(moveX, moveY) || 1;
838:   const nx = moveX / len;
839:   const ny = moveY / len;
840: 
841:   if (Math.abs(moveX) > 0.05 || Math.abs(moveY) > 0.05) {
842:     p.facing.x = nx;
843:     p.facing.y = ny;
844:     const moveSpeed = p.speed * (0.7 + p.stamina / 140);
845:     p.x += nx * moveSpeed * dt;
846:     p.y += ny * moveSpeed * dt;
847:     p.stamina = Math.max(0, p.stamina - dt * 8);
848:   } else {
849:     p.stamina = Math.min(p.maxStamina, p.stamina + dt * 12);
850:   }
851: 
852:   p.x = clamp(p.x, 35, state.mapSize - 35);
853:   p.y = clamp(p.y, 35, state.mapSize - 35);
854:   state.camera.x = p.x;
855:   state.camera.y = p.y;
856:   ui.touchHint.classList.toggle('hidden', state.input.active);
857:   showCampAction();
858:   syncHud();
859: }
