861: function updateProjectiles(dt) {
862:   for (const projectile of state.projectiles) {
863:     projectile.x += projectile.vx * dt;
864:     projectile.y += projectile.vy * dt;
865:     projectile.life -= dt;
866: 
867:     for (const enemy of state.enemies) {
868:       if (!enemy || projectile.from !== 'player') continue;
869:       if (dist(enemy, projectile) < enemy.radius + projectile.radius) {
870:         enemy.hp -= projectile.damage;
871:         projectile.life = 0;
872:         createBurst(projectile.x, projectile.y, '#fdd67b');
873:         break;
874:       }
875:     }
876:   }
877: 
878:   state.projectiles = state.projectiles.filter((proj) => proj.life > 0 && proj.x > 0 && proj.x < state.mapSize && proj.y > 0 && proj.y < state.mapSize);
879: }
