504: function applyInventory(kind, amount = 1) {
505:   if (!state.player.inventory[kind] && !RESOURCE_TYPES[kind]) return false;
506:   if (!state.player.inventory[kind]) state.player.inventory[kind] = 0;
507:   state.player.inventory[kind] += amount;
508:   return true;
509: }
