511: function spendInventory(recipe) {
512:   for (const [key, value] of Object.entries(recipe.cost)) {
513:     if ((state.player.inventory[key] || 0) < value) return false;
514:   }
515:   for (const [key, value] of Object.entries(recipe.cost)) {
516:     state.player.inventory[key] -= value;
517:   }
518:   return true;
519: }
