521: function levelUpIfNeeded() {
522:   const p = state.player;
523:   while (p.xp >= p.nextLevelExp) {
524:     p.xp -= p.nextLevelExp;
525:     p.level += 1;
526:     p.nextLevelExp = Math.round(p.nextLevelExp * 1.42);
527:     p.maxHp += 12;
528:     p.maxMana += 6;
529:     p.maxStamina += 8;
530:     p.hp = p.maxHp;
531:     p.mana = p.maxMana;
532:     p.stamina = p.maxStamina;
533:     logMessage(`Nivel ${p.level} alcanzado. Resistencia reforzada.`, 'warn');
534:   }
535: }
