767: function performAttack() {
768:   const p = state.player;
769:   if (!p || p.attackCooldown > 0) return;
770:   p.attackCooldown = 0.35;
771:   const target = findNearestEnemy(150);
772:   const dir = target ? { x: target.x - p.x, y: target.y - p.y } : p.facing;
773:   const len = Math.hypot(dir.x, dir.y) || 1;
774:   const vx = (dir.x / len) * 320;
775:   const vy = (dir.y / len) * 320;
776:   state.projectiles.push({
777:     x: p.x,
778:     y: p.y,
779:     vx,
780:     vy,
781:     radius: 8,
782:     damage: p.attackDamage || 18,
783:     color: '#f9d894',
784:     life: 0.7,
785:     from: 'player'
786:   });
787:   if (target) {
788:     target.hp -= (p.attackDamage || 18) * 0.9;
789:     logMessage(`${p.className} golpea: ${target.name}`, 'warn');
790:   }
791:   p.stamina = Math.max(0, p.stamina - 5);
792:   syncHud();
793: }
794: 
795: function dodge() {
796:   const p = state.player;
797:   if (!p || p.dodgeCooldown > 0) return;
798:   p.dodgeCooldown = 1.6;
799:   p.invulnerable = 0.65;
800:   const dirX = p.facing.x || 1;
801:   const dirY = p.facing.y || 0;
802:   p.x += dirX * 45;
803:   p.y += dirY * 45;
804:   p.stamina = Math.max(0, p.stamina - 18);
805:   logMessage('Golpe de evasión ejecutado.', 'warn');
806:   syncHud();
807: }
