822: function updatePlayer(dt) {
823:   const p = state.player;
824:   if (!p) return;
825: 
826:   p.attackCooldown = Math.max(0, p.attackCooldown - dt);
827:   p.dodgeCooldown = Math.max(0, p.dodgeCooldown - dt);
828:   p.invulnerable = Math.max(0, p.invulnerable - dt);
829:   p.satiety = Math.max(0, p.satiety - dt * 0.9);
830: 
831:   if (p.satiety <= 0) {
832:     p.hp -= dt * 7;
833:     if (p.hp <= 0) die();
834:   }
835: 
836:   const moveX = state.input.x;
837:   const moveY = state.input.y;
838:   const len = Math.hypot(moveX, moveY) || 1;
839:   const nx = moveX / len;
840:   const ny = moveY / len;
841: 
842:   if (Math.abs(moveX) > 0.05 || Math.abs(moveY) > 0.05) {
843:     p.facing.x = nx;
844:     p.facing.y = ny;
845:     const moveSpeed = p.speed * (0.7 + p.stamina / 140);
846:     p.x += nx * moveSpeed * dt;
847:     p.y += ny * moveSpeed * dt;
848:     p.stamina = Math.max(0, p.stamina - dt * 8);
849:   } else {
850:     p.stamina = Math.min(p.maxStamina, p.stamina + dt * 12);
851:   }
852: 
853:   p.x = clamp(p.x, 35, state.mapSize - 35);
854:   p.y = clamp(p.y, 35, state.mapSize - 35);
855:   state.camera.x = p.x;
856:   state.camera.y = p.y;
857:   ui.touchHint.classList.toggle('hidden', state.input.active);
858:   showCampAction();
859:   syncHud();
860: }
