862: function updateProjectiles(dt) {
863:   for (const projectile of state.projectiles) {
864:     projectile.x += projectile.vx * dt;
865:     projectile.y += projectile.vy * dt;
866:     projectile.life -= dt;
867: 
868:     for (const enemy of state.enemies) {
869:       if (!enemy || projectile.from !== 'player') continue;
870:       if (dist(enemy, projectile) < enemy.radius + projectile.radius) {
871:         enemy.hp -= projectile.damage;
872:         projectile.life = 0;
873:         createBurst(projectile.x, projectile.y, '#fdd67b');
874:         break;
875:       }
876:     }
877:   }
878: 
879:   state.projectiles = state.projectiles.filter((proj) => proj.life > 0 && proj.x > 0 && proj.x < state.mapSize && proj.y > 0 && proj.y < state.mapSize);
880: }
881: 
882: function updateEnemies(dt) {
883:   for (const enemy of state.enemies) {
884:     if (!enemy) continue;
885:     const dx = state.player.x - enemy.x;
886:     const dy = state.player.y - enemy.y;
887:     const distToPlayer = Math.hypot(dx, dy) || 1;
888:     if (distToPlayer < 480) {
889:       enemy.x += (dx / distToPlayer) * enemy.speed * dt;
890:       enemy.y += (dy / distToPlayer) * enemy.speed * dt;
891:     }
892: 
893:     enemy.attackCooldown = Math.max(0, enemy.attackCooldown - dt);
894:     if (distToPlayer < enemy.radius + state.player.radius + 12 && enemy.attackCooldown <= 0) {
895:       const damage = Math.max(4, enemy.damage - (state.player.classId % 4));
896:       state.player.hp -= damage;
897:       state.player.invulnerable = 0.2;
898:       createBurst(state.player.x, state.player.y, '#ff7a7a');
899:       logMessage(`${enemy.name} te golpea por ${damage}.`, 'bad');
900:       enemy.attackCooldown = 0.8;
901:       if (state.player.hp <= 0) {
902:         die();
903:         return;
904:       }
905:     }
906: 
907:     if (enemy.hp <= 0) {
908:       state.player.xp += enemy.xp;
909:       state.player.gold += 4 + Math.floor(Math.random() * 6);
910:       createBurst(enemy.x, enemy.y, '#c9e57d');
911:       state.enemies = state.enemies.filter((item) => item !== enemy);
912:       if (Math.random() < 0.65) {
913:         state.loot.push({
914:           x: enemy.x,
915:           y: enemy.y,
916:           kind: enemy.lootDrop || 'madera',
917:           amount: 1,
918:           radius: 8,
919:           life: 14,
920:           color: RESOURCE_TYPES[enemy.lootDrop]?.color || '#a1d9ad'
921:         });
922:       }
923:       levelUpIfNeeded();
924:       logMessage(`${enemy.name} abatido.`, 'warn');
925:       break;
926:     }
927:   }
928: }
