930: function createBurst(x, y, color) {
931:   for (let i = 0; i < 6; i += 1) {
932:     state.particles.push({
933:       x,
934:       y,
935:       dx: rand(-50, 50),
936:       dy: rand(-50, 50),
937:       radius: rand(2, 5),
938:       life: rand(0.3, 0.7),
939:       color,
940:       alpha: 1,
941:       fromPool: false
942:     });
943:   }
944: }
