946: function updateParticles(dt) {
947:   for (const particle of state.particles) {
948:     particle.x += particle.dx * dt;
949:     particle.y += particle.dy * dt;
950:     particle.life -= dt;
951:     particle.alpha = Math.max(0, particle.life * 1.3);
952:   }
953:   state.particles = state.particles.filter((p) => p.life > 0);
954: }
