970: function die() {
971:   const p = state.player;
972:   const xpLoss = Math.max(0, Math.floor(p.xp * 0.4));
973:   const durabilityLoss = 14 + Math.random() * 16;
974:   p.xp = Math.max(0, p.xp - xpLoss);
975:   p.durability = Math.max(0, p.durability - durabilityLoss);
976:   const corpseInventory = {};
977:   for (const key of Object.keys(p.inventory)) {
978:     const amount = p.inventory[key] || 0;
979:     if (amount > 0 && Math.random() < 0.82) {
980:       corpseInventory[key] = Math.max(1, Math.floor(amount * 0.8));
981:       p.inventory[key] = Math.max(0, Math.floor(amount * 0.2));
982:     }
983:   }
984:   state.corpse = {
985:     x: p.x,
986:     y: p.y,
987:     title: 'Cadáver del Explorador',
988:     loot: corpseInventory,
989:     active: true,
990:     radius: 26
991:   };
992:   p.hp = p.maxHp * 0.45;
993:   p.mana = p.maxMana * 0.35;
994:   p.stamina = p.maxStamina * 0.55;
995:   p.x = state.map.camp.x + 30;
996:   p.y = state.map.camp.y + 30;
997:   p.gold = Math.max(0, p.gold - 12);
998:   logMessage('Has caído. El cadáver guarda el 80% del botín no bancario.', 'bad');
999:   showToast('Cadáver caído: recupera tu botín en la tumba.');
1000:   saveGame();
1001:   syncHud();
1002: }
