1016: function render() {
1017:   const w = canvas.width;
1018:   const h = canvas.height;
1019:   ctx.clearRect(0, 0, w, h);
1020: 
1021:   const px = state.camera.x - w / 2;
1022:   const py = state.camera.y - h / 2;
1023: 
1024:   ctx.fillStyle = '#19251d';
1025:   ctx.fillRect(0, 0, w, h);
1026: 
1027:   ctx.save();
1028:   ctx.translate(-px, -py);
1029: 
1030:   const mapColor = state.map?.tier === 1 ? '#5e7d57' : state.map?.tier === 2 ? '#67775b' : state.map?.tier === 3 ? '#7a8da2' : state.map?.tier === 4 ? '#5d4f7e' : '#3d3d4a';
1031:   ctx.fillStyle = mapColor;
1032:   ctx.fillRect(0, 0, state.mapSize, state.mapSize);
1033: 
