782:     damage: p.attackDamage || 18,
783:     color: '#f9d894',
784:     life: 0.7,
785:     from: 'player'
786:   });
787:   if (target) {
788:     target.hp -= (p.attackDamage || 18) * 0.9;
789:     logMessage(`${p.className} golpea: ${target.name}`, 'warn');
790:   }
791:   p.stamina = Math.max(0, p.stamina - 5);
792:   syncHud();
