809: function findNearestEnemy(range = 200) {
810:   let nearest = null;
811:   let nearestDistance = Infinity;
812:   for (const enemy of state.enemies) {
813:     const d = dist(enemy, state.player);
814:     if (d < range && d < nearestDistance) {
815:       nearest = enemy;
816:       nearestDistance = d;
817:     }
818:   }
819:   return nearest;
820: }
