956: function updateLoot(dt) {
957:   for (const item of state.loot) {
958:     item.life -= dt;
959:     if (dist(item, state.player) < 28) {
960:       applyInventory(item.kind, item.amount);
961:       state.player.gold += 1;
962:       showToast(`${RESOURCE_TYPES[item.kind]?.name || item.kind} recogido.`);
963:       state.loot = state.loot.filter((entry) => entry !== item);
964:       break;
965:     }
966:   }
967:   state.loot = state.loot.filter((item) => item.life > 0);
968: }
