1004: function updateCorpses() {
1005:   if (!state.corpse) return;
1006:   if (dist(state.corpse, state.player) < 40) {
1007:     const bodyLoot = Object.entries(state.corpse.loot || {});
1008:     if (bodyLoot.length) {
1009:       bodyLoot.forEach(([key, amount]) => applyInventory(key, amount));
1010:       logMessage('Cadáver recuperado: tu botín vuelve a ti.', 'warn');
1011:     }
1012:     state.corpse = null;
1013:   }
1014: }
