1016: function render() {
1017:   const w = canvas.width;
1018:   const h = canvas.height;
1019:   ctx.clearRect(0, 0, w, h);
1020: 
1021:   const px = state.camera.x - w / 2;
1022:   const py = state.camera.y - h / 2;
1023: 
1024:   ctx.fillStyle = '#19251d';
1025:   ctx.fillRect(0, 0, w, h);
1026: 
1027:   ctx.save();
1028:   ctx.translate(-px, -py);
1029: 
1030:   const mapColor = state.map?.tier === 1 ? '#5e7d57' : state.map?.tier === 2 ? '#67775b' : state.map?.tier === 3 ? '#7a8da2' : state.map?.tier === 4 ? '#5d4f7e' : '#3d3d4a';
1031:   ctx.fillStyle = mapColor;
1032:   ctx.fillRect(0, 0, state.mapSize, state.mapSize);
1033: 
1034:   for (let x = 0; x <= state.mapSize; x += 120) {
1035:     ctx.strokeStyle = 'rgba(255,255,255,0.03)';
1036:     ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, state.mapSize); ctx.stroke();
1037:   }
1038:   for (let y = 0; y <= state.mapSize; y += 120) {
1039:     ctx.strokeStyle = 'rgba(255,255,255,0.03)';
1040:     ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(state.mapSize, y); ctx.stroke();
1041:   }
1042: 
1043:   const camp = state.map?.camp || { x: 220, y: 220 };
1044:   ctx.fillStyle = '#d18d55';
1045:   ctx.beginPath(); ctx.arc(camp.x, camp.y, 44, 0, Math.PI * 2); ctx.fill();
1046:   ctx.fillStyle = '#f6d3a2';
1047:   ctx.fillRect(camp.x - 12, camp.y - 10, 24, 20);
1048: 
1049:   for (const node of state.resources) {
1050:     ctx.fillStyle = node.color;
1051:     ctx.beginPath(); ctx.arc(node.x, node.y, node.radius, 0, Math.PI * 2); ctx.fill();
1052:   }
1053: 
1054:   for (const enemy of state.enemies) {
1055:     ctx.fillStyle = enemy.color;
1056:     ctx.beginPath(); ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2); ctx.fill();
1057:     ctx.fillStyle = 'rgba(0,0,0,0.45)';
1058:     ctx.fillRect(enemy.x - 18, enemy.y - 26, 36, 4);
1059:     ctx.fillStyle = '#ef7d7d';
1060:     ctx.fillRect(enemy.x - 18, enemy.y - 26, 36 * (enemy.hp / enemy.maxHp), 4);
1061:   }
1062: 
1063:   for (const item of state.loot) {
1064:     ctx.fillStyle = item.color || '#d7c68f';
1065:     ctx.beginPath(); ctx.arc(item.x, item.y, item.radius, 0, Math.PI * 2); ctx.fill();
1066:   }
1067: 
1068:   if (state.corpse) {
1069:     ctx.fillStyle = '#8a8379';
1070:     ctx.beginPath(); ctx.arc(state.corpse.x, state.corpse.y, 16, 0, Math.PI * 2); ctx.fill();
1071:     ctx.fillStyle = '#d0cab1';
1072:     ctx.fillRect(state.corpse.x - 12, state.corpse.y + 10, 24, 10);
1073:   }
1074: 
1075:   for (const p of state.particles) {
1076:     ctx.fillStyle = p.color.replace(')', `, ${Math.max(0, p.alpha)})`).replace('hsl', 'hsla');
1077:     ctx.beginPath(); ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2); ctx.fill();
1078:   }
1079: 
1080:   const player = state.player;
1081:   if (player) {
1082:     ctx.fillStyle = '#d9e6f1';
1083:     ctx.beginPath(); ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2); ctx.fill();
1084:     ctx.fillStyle = '#f9da7a';
1085:     const aimX = player.x + player.facing.x * 18;
1086:     const aimY = player.y + player.facing.y * 18;
1087:     ctx.beginPath(); ctx.moveTo(player.x, player.y); ctx.lineTo(aimX, aimY); ctx.strokeStyle = '#f9da7a'; ctx.lineWidth = 3; ctx.stroke();
1088:   }
1089: 
1090:   for (const projectile of state.projectiles) {
1091:     ctx.fillStyle = projectile.color;
1092:     ctx.beginPath(); ctx.arc(projectile.x, projectile.y, projectile.radius, 0, Math.PI * 2); ctx.fill();
1093:   }
1094: 
1095:   ctx.restore();
1096: 
1097:   drawMinimap();
1098: }
