1116:   mini.fillStyle = '#f5cf84';
1117:   mini.fillRect(state.player.x * scale - 3, state.player.y * scale - 3, 6, 6);
1118:   mini.strokeStyle = '#d0dfe7';
1119:   mini.strokeRect(0, 0, size, size);
1120: }
