387:   const nodes = [];
388:   for (let i = 0; i < 24; i += 1) {
389:     const kind = resourcePool[(i + index) % resourcePool.length];
390:     const x = 100 + Math.random() * (state.mapSize - 200);
391:     const y = 100 + Math.random() * (state.mapSize - 200);
392:     if (dist({ x, y }, { x: map.camp.x, y: map.camp.y }, 140) < 140) continue;
393:     nodes.push({
394:       id: `node-${i}`,
395:       kind,
396:       x,
397:       y,
398:       amount: 1 + Math.floor(Math.random() * 3),
399:       radius: 18,
400:       color: RESOURCE_TYPES[kind]?.color || '#d1d5cc'
401:     });
402:   }
403:   state.resources = nodes;
404: 
405:   const enemyNames = ENEMY_LIBRARY.filter((e) => e.id % (index + 2) !== 0).slice(0, 12 + index % 5);
406:   const enemies = [];
