408:     const e = enemyNames[i];
409:     const node = nodes[i % nodes.length];
410:     enemies.push({
411:       id: `${index}-${i}`,
412:       name: `${e.name} · ${map.name}`,
413:       x: node ? node.x + rand(-80, 80) : rand(300, state.mapSize - 300),
