422:       attackCooldown: 0,
423:       isBoss: false,
424:       lootDrop: ['madera', 'piedra', 'hierba', 'piel', 'carbón'][i % 5]
425:     });
426:   }
427:   if (index === MAPS.length - 1) {
428:     enemies.push({
429:       id: 'boss-final',
430:       name: 'Avatar de la Niebla',
431:       x: state.mapSize - 420,
