422:   const nodes = [];
423:   for (let i = 0; i < 24; i += 1) {
424:     const kind = resourcePool[(i + index) % resourcePool.length];
425:     const x = 100 + Math.random() * (state.mapSize - 200);
426:     const y = 100 + Math.random() * (state.mapSize - 200);
