757: function getNearestResource() {
758:   let best = null;
759:   for (const node of state.resources) {
760:     if (dist(node, state.player) < 64 && (!best || dist(node, state.player) < dist(best, state.player))) {
761:       best = node;
762:     }
763:   }
764:   return best;
765: }
