773:   const value = near.amount ?? 1;
774:   applyInventory(near.kind, value);
775:   showToast(`${RESOURCE_TYPES[near.kind]?.name || near.kind} recogido.`);
776:   state.resources = state.resources.filter((node) => node !== near);
777:   state.loot.push(createRewardLootFromNode(near));
778:   state.player.xp += 5;
779:   levelUpIfNeeded();
780:   syncHud();
781: }
